// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        vm.prank(address(0));
        c.transferOwnership(actor);

        address before = c.owner();
        assertTrue(before == actor);

        vm.prank(actor);
        c.owned();

        assertTrue(c.owner() == before);
    }
}
